	// Each step prints its own report — successes to w, warnings to errW — and
	// only feeds back whether it failed. Failures in Entire's own steps fail the
	// command; external plugin problems do so only under --strict, since they
	// are third-party code Entire cannot fix.

	// 1. Remove agent hooks
	builtinProblem, externalProblem := removeAgentHooks(ctx, w, errW, repoRoot, agHookState)
	requiredFailed := builtinProblem || (strict && externalProblem)

	// 2. Remove git hooks
	if removed, err := strategy.RemoveGitHook(ctx); err != nil {
		fmt.Fprintf(errW, "Warning: failed to remove git hooks: %v\n", err)
		requiredFailed = true
	} else if removed > 0 {
		fmt.Fprintf(w, "  Removed git hooks (%d)\n", removed)
	}

	// 3. Remove session state files
	if statesRemoved, err := removeAllSessionStates(ctx); err != nil {
		fmt.Fprintf(errW, "Warning: failed to remove session states: %v\n", err)
		requiredFailed = true
	} else if statesRemoved > 0 {
		fmt.Fprintf(w, "  Removed session states (%d)\n", statesRemoved)
	}

	// 4. Remove .entire/ directory — kept when external plugin hooks may remain.
	// The external_agents setting gating plugin discovery lives in it, so
	// deleting it would make this very uninstall unrepeatable: a re-run could no
