	if externalProblem {
		if entireDirExists {
			fmt.Fprintln(w, "  Kept .entire directory so re-running `entire disable --uninstall` can retry the external agent hooks")
		}
	} else if err := removeEntireDirectory(ctx); err != nil {
		fmt.Fprintf(errW, "Warning: failed to remove .entire directory: %v\n", err)
		requiredFailed = true
	} else if entireDirExists {
		fmt.Fprintln(w, "  Removed .entire directory")
