// reportUninstallOutcome prints the closing status line and decides the exit
// code from facts the steps already judged. ok is the steps' combined verdict
// with strict policy included — a strict-fatal external problem arrives here
// as ok=false, so no strictness is re-derived. externalProblem only picks the
// honest wording for a run that succeeded by policy while plugin hooks may
// remain.
func reportUninstallOutcome(w io.Writer, ok, externalProblem bool) error {
	switch {
	case !ok:
		fmt.Fprintln(w, "\nEntire CLI uninstall did not complete - see the warnings above.")
		return NewSilentError(errors.New("uninstall did not complete"))
	case externalProblem:
		fmt.Fprintln(w, "\nEntire CLI uninstalled, but some external agent hooks may remain - see the warnings above.")
		return nil
	default:
		fmt.Fprintln(w, "\nEntire CLI uninstalled successfully.")
		return nil
	}
}

